640	     * @param email the owner's email, possibly {@code null}
641	     * @param lastName the owner's last name, possibly {@code null}
642	     * @param postcode the owner's postcode, possibly {@code null}
643	     * @return the identity key, never {@code null}
644	     */
645	    public static String identityKey(String telephone, String email, String lastName, String postcode) {
646	        String normalizedTelephone = normalizeTelephone(telephone);
647	        String normalizedEmail = normalizeEmail(email);
648	        String household = householdId(lastName, postcode);
649	        return (normalizedTelephone == null ? "" : normalizedTelephone)
650	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
651	            + "|" + (household == null ? "" : household);
652	    }
653	
654	    /**
655	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
656	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
657	     * is the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). The
658	     * value is deterministic in those two fields.
659	     *
660	     * @param customerCode the owner's customer code, possibly {@code null}
661	     * @param registrationDate the owner's registration date, possibly {@code null}
662	     * @return the membership number, or {@code null} if either field is {@code null}
663	     */
664	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
665	        if (customerCode == null || registrationDate == null) {
666	            return null;
667	        }
668	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
669	    }
670	
671	    /**
672	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
673	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
674	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
